const e={title:"TripReel - تطبيق الرسوم المتحركة للسفر المجاني: حوّل الصور إلى فيديوهات جميلة",description:"أنشئ فيديوهات سفر مذهلة مع خرائط متحركة ومسارات طيران. تطبيق رسوم متحركة للسفر مجاني مع رسم خرائط مسار الكرة الأرضية ثلاثي الأبعاد. حوّل صورك إلى فيديوهات رحلة جميلة تلقائيًا. الخصوصية أولاً، يعمل دون اتصال.",keywords:"تطبيق الرسوم المتحركة للسفر, تطبيق الرسوم المتحركة لخريطة السفر, تطبيق الرسوم المتحركة لمسار السفر, تطبيق الرسوم المتحركة للطيران, صانع فيديو السفر, فيديو السفر التلقائي, خريطة السفر المتحركة, رسوم متحركة مسار الطيران, رسوم متحركة السفر, رسوم متحركة الكرة الأرضية, فيديو مراجعة السفر, صورة إلى فيديو, لمحات السفر, تطبيق السفر المجاني, صانع فيديو دون اتصال, تطبيق السفر الخاص, فيديو لفة الكاميرا"},t={logoAlt:"شعار TripReel",appName:"TripReel",howItWorks:"كيف يعمل",video:"فيديو",features:"المميزات",theApp:"التطبيق"},i={badge:"حوّل صورك إلى قصص سفر",title1:"ألبوم الصور لديك،",title2:"في أبهى حلة",description:"يُنشئ TripReel تلقائيًا فيديوهات سفر رائعة من مواقع صورك. شاهد رحلاتك تنبض بالحياة مع خرائط مسارات متحركة ومسارات طيران على كرة أرضية ثلاثية الأبعاد، مع الحفاظ على خصوصية بياناتك وأمانها.",secure:"آمن بنسبة 100%",worksOffline:"يعمل دون اتصال",globeAlt:"رسوم متحركة للكرة الأرضية TripReel"},r={title:"كيف يعمل",subtitle:"ثلاث خطوات بسيطة لإنشاء فيديو السفر المثالي",step1:{title:"السماح بالوصول للصور",description:"امنح TripReel إذن الوصول إلى مكتبة الصور. يقرأ التطبيق فقط بيانات الموقع، ولا شيء غير ذلك."},step2:{title:"اكتشاف تلقائي للرحلات",description:"يحلل TripReel بيانات الموقع ويكتشف رحلاتك بذكاء استنادًا إلى التواريخ والمواقع."},step3:{title:"إنشاء الفيديو",description:"شاهد رحلتك تتكشف على رسوم متحركة جميلة للكرة الأرضية، جاهزة للمشاركة على وسائل التواصل."}},s={title:"شاهد السحر يحدث",subtitle:"اكتشف كيف يحول TripReel مكتبة صورك إلى فيديوهات سفر مذهلة",caption:"هكذا سيبدو فيديو السفر النهائي"},o={title:"كل ما تحتاجه",subtitle:"مميزات قوية مصممة للمسافرين المعاصرين",twoTap:{title:"فيديوهات سفر بلمستين",description:"أنشئ فيديوهات سفر رائعة من مكتبة صورك بلمستين فقط. لا حاجة للتحرير."},smartTrip:{title:"كشف ذكي للرحلات",description:"يجد ويجمع رحلاتك تلقائيًا عن طريق تحليل التواريخ وبيانات الموقع من صورك."},globe:{title:"رسوم متحركة جميلة للكرة الأرضية",description:"شاهد رحلتك تنبض بالحياة مع كرة أرضية ثلاثية الأبعاد مذهلة تعرض مساراتك المتحركة ومسارات الطيران حول العالم."},privacy:{title:"الخصوصية أولًا",description:"تتم المعالجة بالكامل على جهازك. صورك لا تغادر هاتفك أبدًا. يعمل في وضع الطيران."},customStyles:{title:"أنماط قابلة للتخصيص",description:"اختر من بين أنماط متعددة للكرة الأرضية وخيارات تخصيص لتناسب ذوقك وتجعل كل فيديو فريدًا."},manualControl:{title:"تحكم يدوي",description:"يمكنك إضافة رحلات جديدة يدويًا إذا لم تكن خدمات الموقع مفعلة على جهازك."}},l={title:"أفكار إبداعية للفيديو",subtitle:"استلهم أفكارًا لما يمكنك إنشاؤه باستخدام TripReel. من رحلات نهاية الأسبوع القصيرة إلى مغامرات تمتد لعام كامل، أنشئ فيديوهات سفر مذهلة لكل رحلة.",description:"سواء كنت تُنشئ رسومًا متحركة لخريطة سفر، أو توثق مسار رحلة طيران، أو تصنع ملخصًا سنويًا لرحلاتك، يجعل TripReel من السهل تحويل ذكرياتك إلى فيديوهات قابلة للمشاركة.",ideas:{yearRecap:{title:"ملخص رحلات 2025",description:"أنشئ فيديو ملخص رحلاتك لعام 2025 تلقائيًا"},europeRoadTrip:{title:"رحلة بالسيارة في أوروبا",description:"اعرض مغامرتك الأوروبية بخرائط مسارات متحركة"},southeastAsia:{title:"رحلة جنوب شرق آسيا",description:"تصور مسارك عبر بلدان متعددة"},japanRail:{title:"رحلة بالقطار في اليابان",description:"أنشئ فيديوهات خرائط لمسارات قطاراتك في اليابان"},crossCountry:{title:"عبور الولايات المتحدة",description:"حوّل رحلتك الأمريكية إلى فيديو مسار ملحمي"},islandHopping:{title:"التنقل بين الجزر",description:"اعرض رحلاتك من جزيرة إلى أخرى برسوم متحركة ثلاثية الأبعاد مذهلة"},worldTour:{title:"مونتاج جولة عالمية",description:"عدة رحلات في فيديو رحلة عالمي واحد مذهل"},travelPlans:{title:"خطط السفر لعام 2026",description:"تصور وخطط لمغامرات سفرك المثيرة لعام 2026"},lifetimeTravel:{title:"قصة السفر مدى الحياة",description:"أنشئ فيديو يعرض جميع رحلاتك مدى الحياة"},regionalExplorer:{title:"مستكشف إقليمي",description:"ارسم مغامراتك عبر الولايات والمقاطعات والمناطق"},festivalCircuit:{title:"دائرة المهرجانات",description:"ارسم خريطة رحلتك عبر مهرجانات الموسيقى والفعاليات"},bikeRoutes:{title:"رحلاتي إلى المدن",description:"اعرض جميع هروبك إلى المدن"}}},a={title:"التطبيق",subtitle:"متوفر الآن على App Store",alt1:"فيديوهات سفر تلقائية - أنشئ فيديوهات مذهلة في ثوانٍ",alt2:"كشف موقع الصور - يستخدم بيانات صورك",alt3:"كشف الرحلات - يجمع رحلاتك تلقائيًا",alt4:"فيديوهات الكرة الأرضية الجميلة - رسوم متحركة للكرة الأرضية لرحلتك",alt5:"أنماط مخصصة - خصّص فيديوهات سفرك"},n={comingSoon:"قريبًا",androidTitle:"تطبيق أندرويد قريبًا!",androidMessage:'إصدار أندرويد غير متوفر حاليًا لكنه سيكون قريبًا. راسلني على <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> وسأخبرك عندما يكون جاهزًا!',gotIt:"فهمت!"},p={title:"الأسئلة الشائعة",subtitle:"كل ما تحتاج معرفته عن TripReel",q1:{question:"هل يمكنني حقًا استخدام التطبيق بالكامل في وضع الطيران؟",answer:"نعم! بالنسبة للمستخدمين المميزين، يمكن استخدام التطبيق بالكامل دون اتصال في وضع الطيران دون أي قيود. بالنسبة للمستخدمين غير المميزين، بعض المميزات مدعومة بالإعلانات والتي قد تتطلب تفعيل الإنترنت مؤقتًا، ولكن بالنسبة للمستخدمين المميزين لا توجد إعلانات ويمكن استخدام التطبيق بالكامل في وضع الطيران."},q2:{question:"قمت بالترقية إلى Premium، كيف يمكنني إزالة العلامة المائية؟",answer:"يسأل الكثيرون عن التطبيق المستخدم لإنشاء هذه الفيديوهات، لذا بعد الترقية إلى المميز، لديك خيار إضافة نسخة أصغر من العلامة المائية (باسم التطبيق فقط) أو إزالتها تمامًا إذا أردت."},q3:{question:"هل بيانات صوري آمنة وخاصة؟",answer:"بالتأكيد! يقرأ TripReel فقط بيانات الموقع من صورك - لا نصل أبدًا إلى محتوى الصور الفعلي أو نخزنه أو ننقله. تتم المعالجة بالكامل محليًا على جهازك، ولا تغادر أي بيانات هاتفك. يمكنك التحقق من ذلك باستخدام التطبيق في وضع الطيران - يعمل بشكل مثالي دون اتصال!"},q4:{question:"ماذا لو لم تكن صوري تحتوي على بيانات الموقع؟",answer:"لا مشكلة! إذا لم تكن خدمات الموقع مفعلة عند التقاط صورك، يمكنك إنشاء رحلات يدويًا وإضافة مواقع بنفسك. يمنحك التطبيق تحكمًا كاملاً لتخصيص جدول رحلاتك الزمني."},q5:{question:"كيف يكتشف التطبيق رحلاتي تلقائيًا؟",answer:"يحلل TripReel بيانات الموقع والطوابع الزمنية من صورك ليحدد بذكاء متى وأين سافرت. يجمع المواقع والتواريخ القريبة لاكتشاف رحلاتك تلقائيًا دون أي عمل يدوي مطلوب."},q6:{question:"هل يمكنني تخصيص مظهر فيديوهاتي؟",answer:"نعم! يمكنك الاختيار من بين أنماط متعددة للكرة الأرضية وتخصيص جوانب مختلفة من فيديوهات سفرك المتحركة لتناسب ذوقك الشخصي. يحصل المستخدمون المميزون على مزيد من أنماط الرسوم المتحركة للمسارات وثيمات الخرائط وخيارات مسارات الطيران."},q7:{question:"هل أحتاج لإنشاء حساب؟",answer:"لا حاجة لحساب! يعمل TripReel فورًا بعد التنزيل. لا توجد عملية تسجيل، ولا تسجيل دخول، ولا حاجة لمعلومات شخصية. فقط نزّل التطبيق وابدأ بإنشاء فيديوهات سفرك على الفور."},q8:{question:"لماذا يفتقد موقع من رحلتي؟",answer:"يمكن للتطبيق العمل فقط بالبيانات المتاحة، لذا أولاً تحتاج على الأقل إلى بضع صور في ذلك الموقع. ثانيًا، تحتاج للتأكد من أن بيانات الموقع كانت مفعلة عندما كنت هناك. ثالثًا، أحيانًا استقبال GPS الضعيف قد يتسبب في بيانات موقع خاطئة. إذا استبعدت كل هذا ولا يزال موقعك لا يظهر، يمكنك إضافة ذلك الموقع يدويًا من Trips Overview > زر Edit. يرجى أيضًا استخدام Contact للإبلاغ عن المشكلة."},q9:{question:"أين يمكنني مشاركة فيديوي الرائع؟",answer:"بالطبع، يمكنك أيضًا مشاركته على جميع منصات التواصل الاجتماعي. لتناسب المنصة بشكل أفضل، يتيح التطبيق نسب عرض مختلفة لفيديوهاتك."},q10:{question:"أين يمكنني الإبلاغ عن خطأ؟",answer:"فقط راسلني مباشرة على marian@qod.ee، واشرح بإيجاز ما هي المشكلة."}},c={title:"الدعم عبر البريد الإلكتروني",description:"إذا كان لديك أي ملاحظات أو واجهت أي مشكلات، لا تتردد في التواصل معي مباشرة على هذا البريد الإلكتروني وسأقرأ وأتعامل شخصيًا مع طلبك بأسرع ما يمكن. شكرًا لاستخدامك التطبيق!",close:"إغلاق"},d={default:{title:"🍪 ملفات تعريف الارتباط",message:"نستخدم ملفات تعريف الارتباط على موقع TripReel لتحسين تجربتك. لا يتم جمع بيانات شخصية.",accept:"قبول",decline:"رفض",details:"التفاصيل"},theme:{title:"🍪 ملفات تعريف الارتباط",message:"🌙 لحفظ تفضيل الثيم، تحتاج لقبول ملفات تعريف الارتباط الأساسية على موقع TripReel. بدونها، لا يمكن حفظ اختيار الثيم.",accept:"قبول",decline:"رفض",details:"التفاصيل"}},u={privacy:"سياسة خصوصية التطبيق",cookies:"سياسة ملفات تعريف الارتباط للموقع",contact:"اتصل بنا",cookiePreferences:"تفضيلات ملفات تعريف الارتباط",madeWith:"صُنع بـ",forTravelers:"للمسافرين حول العالم",copyright:"© {{year}} TripReel."},T={title:"هل أنت مستعد لمشاركة رحلتك؟",description:"نزّل TripReel اليوم وحوّل ألبوم صورك إلى فيديوهات سفر جميلة مع خرائط ومسارات متحركة. مغامراتك تستحق الاحتفاء بها.",features:"تنزيل مجاني • سريع ومريح • الخصوصية مضمونة"},q={meta:e,header:t,hero:i,howItWorks:r,videoSection:s,features:o,videoIdeas:l,screenshots:a,appStore:n,faq:p,contact:c,cookieBanner:d,footer:u,cta:T};export{n as appStore,c as contact,d as cookieBanner,T as cta,q as default,p as faq,o as features,u as footer,t as header,i as hero,r as howItWorks,e as meta,a as screenshots,l as videoIdeas,s as videoSection};
